    ...(catalog.revision!==null||renderer==='sprite'?{motionLibrary:{producer:'actor-motion-catalog-1',snapshotHash:catalog.snapshotHash,renderer:renderer??'authored',entries:catalog.entries,
      rule:'Use only these exact actorId/motionId/fingerprint/state/view/capability versions for spriteStage. Preserve source action statements and target IDs. Capability metadata is candidate, not visual acceptance. Native once action must fit its full duration/rate; do not truncate or mirror. Speech requires clip.speech={variantId,fingerprint,segmentIds} from that motion entry speechVariants/mouthArtwork, plus the same original cue IDs in the owning actorScene speakingSegmentIds and clip narration sourceRefs. Each original cue has one actor owner; adjacent clips may share that owner/cue but must visibly cover its whole intersection with the shot. Body sourcedAction describes registered native movement, not a substitute for a speech binding. Mouth timing is built from original narration/activity by Factory, not supplied by the model. Missing mouth artwork is a blocker; never rewrite dialogue, draw face glyphs or fall back to a rig. No skeletal props or continuous handoff. Root and contact clock is shot-local; preserve narration-global cues. Explicit sprite selection requires spriteStage for actor shots, no rig fallback; object-only cutaways remain allowed. Bounds are frame rectangles, common landmarks are present in every native frame, not certified anatomy.'}}:{}),
    beats:context.beats,host:context.profile,rig:{rigHash:context.rig.rigHash},seed:seed.shots,seedVisualAdvisories:castDesignAdvisories(seed),lockedShots:locks,...(context.lockedActors?.length?{lockedActors:context.lockedActors}:{}),
    dimensions:config.rendering.final,...(config.presentation.design_brief?{designBrief:config.presentation.design_brief}:{}),artworkCoordinates:'Layers use stage pixels. Models default to normalized-stretch: centered 100x100 is scaled independently into part width/height, including text. Use sourced stage-pixel labels or explicit projection=model-viewport with one complete valid SVG viewBox to preserve its authored aspect policy in the actual part viewport. Recheck geometry and contact if letterboxing changes the illustration. Keyframes use the local shot clock.',
    ...(context.narration.segments.some(cue=>mentionsRunning(cue.text)||mentionsAirborne(cue.text))?{animationCapabilities:ANIMATION_LIBRARY}:{}),
    creativeFreedom:'Choose a visual language for this story. The seed is editable, not a mandatory layout, mood schedule, palette or recipe sequence.'};
  let generationSystem=config.presentation.character_mode==='actors'
    ?system.replace('with stick figures as ACTORS WITHIN THE STORY',`with ${context.profile.kind} performers as ACTORS WITHIN THE STORY`):system;
  if(renderer==='sprite')generationSystem+='\nThe project explicitly selects image-based motion. Design actor shots with cinematic.spriteStage using the supplied motionLibrary versions and sourcedAction capability. Do not substitute skeletal gestures/walks or rewrite source speech to evade an unsupported sprite feature. Legacy performance/header fields describe metadata only in a sprite shot; actual artwork/action comes from registered clips and roots. Keep actorScene continuity=cut until sprite handoff is supported. Preserve the original source and report missing movement capabilities through validation rather than inventing assets.';
  if(config.presentation.character_mode==='actors'&&requestContext.animationCapabilities){
    generationSystem=generationSystem.replace('locomotion needs an actual nonzero walk;',
      'locomotion needs the actual clip matching its movement subtype: movement=jump requires a timed performance.jumps flight/landing; movement=run requires a nonzero walks path with gait=run under compiler performance-2.2.15; movement=walk requires gait=walk or omitted; an omitted movement requires a nonzero locomotion path;');
  }
  const inputHash=hash({identity,system:generationSystem,context:requestContext,models:config.models.storyboard,fallback:config.models.fallback,retry:config.retry.structured_output,schema:DIRECTION_VERSION});
  const binding={modelsHash:hash({primary:config.models.storyboard,fallback:config.models.fallback})};
  if(router.isMock('storyboard')){if(config.topic.id||renderer==='sprite')throw new Error('needs-art-direction: configure a real director or authored direction; an offline seed is not a directed image-motion episode');return report(seed,'offline',inputHash);}
  const cacheFile=path.join(root,'work/creative-storyboard-cache.json');
  if(await exists(cacheFile)){
    const cached=await readJson<{inputHash:string;storyboard:unknown}>(cacheFile);
    if(cached.inputHash===inputHash){try{return await report(await normalize(StoryboardSchema.parse(cached.storyboard),'model'),'model',inputHash);}catch{/* Invalid edits are regenerated through the configured real role. */}}
  }
  // A model response rejected by an earlier validator can become valid after a renderer repair.
  // Reuse only matching current request data/instructions; never relabel edited or unrelated output.
  const attemptsDir=path.join(root,'work/attempts/creative-storyboard');
  let initialRepair:{previous:unknown;feedback:string}|undefined;
  if(await exists(attemptsDir)){
    const files=(await Promise.all((await walk(attemptsDir)).filter(file=>file.endsWith('.json')).map(async file=>({file,mtime:(await fs.stat(file)).mtimeMs})))).sort((a,b)=>b.mtime-a.mtime).map(item=>item.file);
    for(const file of files){
      const attempt=await readJson<{status:string;request?:{system:string;context:unknown};response?:unknown;binding?:unknown}>(file);
      if(attempt.status!=='domain-rejected'||!attempt.response||hash(attempt.binding)!==hash(binding)||hash(attempt.request?.context)!==hash(requestContext)||attempt.request?.system!==generationSystem)continue;
      try{
        const board=await normalize(StoryboardSchema.parse(attempt.response),'model');
        await writeJson(cacheFile,{inputHash,storyboard:board,revalidatedAttempt:path.relative(root,file).split(path.sep).join('/')});
        return report(board,'model',inputHash);
      }catch(error){
        // Resume a matching rejected design with every current failure, keeping its creative work.
        // No response is edited or accepted here; the configured model still supplies the repair.
        initialRepair??={previous:attempt.response,feedback:error instanceof Error?error.message:String(error)};
      }
    }
  }
  // Explain actual approval authority at generation time. Seed preview approval
  // and profile immutable fields do not lock every story actor to the mascot.
  // Accepted designs retain their cache/approval identity and are not redesigned.
  const designBrief=config.presentation.character_mode==='actors'?{
    task:'Design a film of this story, including its cast, world, readable acting and shot composition.',
    productionContract:creativeActingBrief(context.beats,context.narration,context.profile,context.lockedActors),
    selectedRig:{kind:context.profile.kind,profileId:context.profile.id,rule:'Use this selected performer family for the story cast, with freely designed role-specific illustrative appearances. Historical or fictional people are portrayed by actors using this rig; preserve identity facts and explicit approvals.'},
    approvalAuthority:{actorIds:[...new Set([...(context.lockedActors??[]),...actorDefinitions({shots:locks})].map(actor=>actor.id))],shotIds:[...lockIds],
      rule:'Preserve these explicit actor and shot locks. An empty list means there are no approved locks of that kind. The seed host immutable fields and preview describe the base rig, not approved appearances for every story role. Narrated name, role and identity evidence remain immutable for all actors.'},
    cast:'Choose a coherent illustrative design for each sourced role using the selected rig family, passive costume layers and supported proportions. Keep that design identical across their shots. Make co-present roles readable through silhouette, hair, clothing, proportion, shape or color when appropriate; intentional resemblance remains allowed. Seed clones are placeholders, not a required wardrobe. Do not invent biographical facts to justify visual choices.',
    staging:'Choose composition for what the viewer must understand at this moment. Establish place where needed; give meaningful faces, hand work and interactions enough screen space to read. Medium, face detail, object detail and wide shots are available within their canonical focus contracts. A distant full-body view is useful for location or walking, but may conceal a small expression. Recompose across cuts when it improves the story; no shot-size quota or fixed actor percentage applies.',
    world:'Use story-specific passive SVG sets, depth, light, textures, gradients and foreground layers where useful. Distinguish background atmosphere from sourced objects participating in an action. Rain, shadows and camera motion supplement acting, they do not replace it. Do not use a flat seed stage or a machine diagram merely because it was supplied as a scaffold.',
    acting:'Build preparation, change, response and recovery for the actual sourced situation using typed expressions, gaze, body posture, walking, standing jumps and hand gestures. Running requires performance.compilerVersion=performance-2.2.15 and walks[].gait=run, alternating support and a flight phase; a fast walk does not satisfy movement=run. New jumps or drop gestures require performance.compilerVersion=performance-2.2.14 or performance-2.2.15; retain performance-2.2.13 on grounded plans without those tracks. Jumps use startMs/takeoffMs/landingMs/endMs/height, with height in unscaled rig units. Both feet leave the floor in flight; no walk, turn, seated/posture transition or fixed contact can overlap. A drop gesture has propId, carryOffset, contactMs, releaseMs, landingMs and destination (landing grip); its prop.destination is the landing object center. The prop follows the actual held hand until release, then falls preserving horizontal and vertical hand momentum. The landing x equals release x plus measured horizontal velocity times fall duration; do not push a freely dropped prop sideways by inventing a landing x. Target still identifies the original grip. Use the same sourced entity and matching operate-model action/hand clocks, not a decorative duplicate. Match meaningful changes to the narration clock, preserve pauses with purpose, and make the decisive action readable. A moving caption, decorative blink or pan is not a substitute for the narrated actor action. Preserve source statements, contact, bone and capability constraints.',
    worldCoordinates:'Layer geometry uses stage pixels; distinguish depth from coordinate space. Background layers without coordinateSpace stay fixed in the frame for compatibility. Set coordinateSpace=world on a background layer for a floor, road, wall or scenery that should share the actors and objects camera. Its own local keyframes compose inside that camera, behind midground and actors. Use frame for intentionally fixed atmosphere/backdrops; overlay stays frame space. Midground and foreground already share the world camera; do not set coordinateSpace on those or on overlay. Align visual ground with the actual actor groundY and model anchors before projection, and inspect the projected camera move, clipping and subtitle safe area. This does not impose a palette, setting, floor or shot-size quota.',
    motionTiming:'Choose keyframe ease for the actual motion: none means constant rate, sine.in accelerates, sine.out settles, sine.inOut starts and settles. The optional ease belongs to the destination keyframe and affects only its incoming local-clock interval; missing ease keeps the previous smooth curve. Continuous environmental or causal motion should not be stretched into a barely changing full-shot drift. Use sourced geometry and deliberate local phases; preserve actor performance and contact. No loop, callback, wall-clock animation or automatic movement quota is implied.',
    nativeSourceGesture:'For explicitly selected registered native body mouth/eyes only, point/think can declare gesture.sourceSpan with one command id and original absolute start/end, optional reachMs/recoverMs for the arm keypose. This is motion timing, never physical-contact proof or narration timing. In a declared continuous fixed-view run, copy the same span, hand/action/target/pole into every intersecting shot and clip local gesture/action start/end exactly to that shot. Omit local contactMs/releaseMs and prop/contact fields. Supply complete coverage; never infer continuity from similar local ids or coordinates. Keep cast/view/stage/root/scale/profile stable; use an explicit cut or separate complete command when they change. Do not attach sourceSpan to unsupported gestures/props/spears/locomotion. Preserve actual narration/audio clocks, actor identity and approval gates.',
    selfReview:'Before returning, inspect the planned key moments: can a viewer identify the roles, read the expression or operation, follow the causal action and locate the scene? Correct scale, staging or costume in the design if not. Return the complete canonical storyboard; design commentary belongs in artDirection.brief. Do not assert an approval or rendered quality result that did not occur.'
  }:undefined;

  const board=await planWithValidation(root,config,router,'storyboard','creative-storyboard',{system:generationSystem,
    prompt:(designBrief?JSON.stringify(designBrief)+'\n\n':'')+'Return the complete {shots:[...]} production storyboard. Design the scenes with purposeful acting, explanatory motion and a coherent visual language. Keep exact narration, sourced object identity, contact order and approved locks. You may change cuts, world composition, art layers, model SVG, performance, expressions and camera within the canonical schema. Supply artDirection for every unlocked shot. Review visibility and readability before returning. Calculate gesture targets from the actual part bounds and declared anchor in stage pixels. A host react action requires its matching timed react gesture; for a facial-only reaction use an idle arm action with the expressive face track. Keep the intended emotion. Retain the manipulated part sourceRefs in pickup bindings and keep all sceneIntent evidence within verified scene sources. Bound props support one completed in-shot pick-place, carry or drop. Keep continuity.carriedProps empty. Normal pickup requires approach/contact before attachment. An actorScene with continuity=cut may start a sourced operation=drop with an already held prop: prop.attachedTo identifies the hand, drop.startMs=contactMs=0, origin equals the actual entry hand minus gripOffset, and the matching operate-model action begins/contact at the shot start with the current cue anchor. This is explicit entry ownership, not a cross-cut transfer. Preserve source targetIds, landing bounds and clocks. Other entry or cross-cut bound attachments remain unsupported. Check the projected actor feet and visual ground throughout the camera move against the frame and subtitle safe area. Fit walk distance to the available time and rig leg length. When repairing, return the complete design with these constraints resolved; preserve story-specific acting and artwork rather than replacing the scene with a generic presentation.'+`\nRenderer-supported passive SVG tags: ${supportedArtworkTags().join(', ')}. SVG pattern, filter, use, image, style and animate are not supported. Repeated details can use primitive geometry in stage-pixel art layers and existing local-clock keyframes. This capability list does not prescribe a visual style.`,context:requestContext},
    CreativeStoryboardSchema,value=>normalize(value,'model'),binding,initialRepair);
  await writeJson(cacheFile,{inputHash,storyboard:board});
  return report(board,'model',inputHash);
}
